#!/usr/bin/env bash
# Generates code from every contracts/*.schema.json: TypeScript types in worker/src/contracts/
# and Pydantic v2 models in node/src/yt_digest_node/contracts/.
#   ./scripts/contracts.sh          regenerate the committed files
#   ./scripts/contracts.sh --check  regenerate into a temporary directory and exit 1, naming the
#                                   files, when a committed generated file differs
# CONTRACTS_ROOT (default: the repository) is the tree holding the schemas and the generated files;
# the generators always come from the repository.
set -euo pipefail
repo="$(cd "$(dirname "$0")/.." && pwd)"
root="${CONTRACTS_ROOT:-$repo}"
header="Generated by scripts/contracts.sh from contracts/: do not edit."
ts_dir=worker/src/contracts
py_dir=node/src/yt_digest_node/contracts

# generate <out>: writes both generated directories under <out>.
generate() {
  local out=$1 schema name
  mkdir -p "$out/$ts_dir" "$out/$py_dir"
  for schema in "$root"/contracts/*.schema.json; do
    name=$(basename "$schema" .schema.json)
    {
      "$repo/worker/node_modules/.bin/json2ts" --input "$schema" --bannerComment "// $header" --unknownAny
      # The schema itself, for runtime validation.
      printf '\nexport const %sSchema = ' "$(sed -E 's/-(.)/\U\1/g' <<<"$name")"
      sed '$s/$/;/' "$schema"
    } >"$out/$ts_dir/$name.ts"
  done
  uv run --quiet --locked --project "$repo/node" datamodel-codegen \
    --input "$root/contracts" --input-file-type jsonschema --output "$out/$py_dir" \
    --output-model-type pydantic_v2.BaseModel --target-python-version 3.12 \
    --use-specialized-enum --field-constraints --use-standard-collections --use-union-operator \
    --disable-timestamp --custom-file-header "# $header" --formatters builtin
  uv run --quiet --locked --project "$repo/node" ruff check --quiet --fix \
    --config "$repo/node/pyproject.toml" "$out/$py_dir"
  uv run --quiet --locked --project "$repo/node" ruff format --quiet \
    --config "$repo/node/pyproject.toml" "$out/$py_dir"
}

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
generate "$tmp"

case "${1:-}" in
  "")
    for dir in "$ts_dir" "$py_dir"; do
      rm -rf "${root:?}/$dir"
      mkdir -p "$root/$dir"
      cp -R "$tmp/$dir/." "$root/$dir/"
    done
    echo "contracts: generated $ts_dir and $py_dir"
    ;;
  --check)
    stale=()
    for dir in "$ts_dir" "$py_dir"; do
      while IFS= read -r file; do
        if ! cmp -s "$tmp/$file" "$root/$file"; then
          stale+=("$file")
        fi
      done < <(cd "$tmp" && find "$dir" -type f; cd "$root" && find "$dir" -type f -not -path '*/__pycache__/*' 2>/dev/null)
    done
    if ((${#stale[@]})); then
      mapfile -t stale < <(printf '%s\n' "${stale[@]}" | sort -u)
      echo "contracts: generated files are stale, run ./scripts/contracts.sh:" >&2
      printf '  %s\n' "${stale[@]}" >&2
      exit 1
    fi
    echo "contracts: generated files are up to date"
    ;;
  *)
    echo "usage: $0 [--check]" >&2
    exit 2
    ;;
esac
